import React, { useContext, useState, useEffect } from 'react'
import { Helmet } from 'react-helmet'
import { Link, useParams } from 'react-router-dom'
import { makeStyles } from '@material-ui/core/styles'
import { AiOutlineHome } from 'react-icons/ai'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import rehypeRaw from 'rehype-raw'

import './ProjectDetailPage.css'
import { ThemeContext } from '../../contexts/ThemeContext'
import { projectsData } from '../../data/projectsData'
import { headerData } from '../../data/headerData'

function generateSlug(children) {
    const text = Array.isArray(children)
        ? children.map((c) => (typeof c === 'string' ? c : '')).join('')
        : typeof children === 'string'
        ? children
        : ''
    return text
        .toLowerCase()
        .trim()
        .replace(/[^\w\s\uAC00-\uD7AF\u3131-\u3163\u1100-\u11FF-]/g, '')
        .replace(/\s+/g, '-')
}

function ProjectDetailPage() {
    const { id } = useParams()
    const { theme } = useContext(ThemeContext)
    const [markdown, setMarkdown] = useState('')
    const [loading, setLoading] = useState(true)

    const project = projectsData.find((p) => p.id === Number(id))

    useEffect(() => {
        if (!project || !project.mdFile) {
            setLoading(false)
            return
        }

        fetch(`${process.env.PUBLIC_URL}/projects/${project.mdFile}`)
            .then((res) => res.text())
            .then((text) => {
                const converted = text.replace(
                    /https:\/\/github\.com\/([^/]+)\/([^/]+)\/blob\/([^)"\s]+)/g,
                    'https://raw.githubusercontent.com/$1/$2/$3'
                )
                setMarkdown(converted)
                setLoading(false)
            })
            .catch(() => {
                setLoading(false)
            })
    }, [project])

    const useStyles = makeStyles((t) => ({
        home: {
            color: theme.secondary,
            position: 'absolute',
            top: 25,
            left: 25,
            padding: '7px',
            borderRadius: '50%',
            boxSizing: 'content-box',
            fontSize: '2rem',
            cursor: 'pointer',
            boxShadow:
                theme.type === 'dark'
                    ? '3px 3px 6px #ffffff40, -3px -3px 6px #00000050'
                    : '3px 3px 6px #ffffff40, -3px -3px 6px #00000050',
            transition: 'all 0.3s ease-in-out',
            '&:hover': {
                color: theme.tertiary,
                transform: 'scale(1.1)',
            },
            [t.breakpoints.down('sm')]: {
                fontSize: '1.8rem',
            },
        },
    }))

    const classes = useStyles()

    if (!project) {
        return (
            <div
                className='projectDetailPage'
                style={{ backgroundColor: theme.secondary }}
            >
                <div
                    className='projectDetailPage-header'
                    style={{ backgroundColor: theme.primary }}
                >
                    <Link to='/projects'>
                        <AiOutlineHome className={classes.home} />
                    </Link>
                    <h1 style={{ color: theme.secondary }}>
                        Project Not Found
                    </h1>
                </div>
            </div>
        )
    }

    return (
        <div
            className='projectDetailPage'
            style={{ backgroundColor: theme.secondary }}
        >
            <Helmet>
                <title>
                    {headerData.name} | {project.projectName}
                </title>
            </Helmet>
            <div
                className='projectDetailPage-header'
                style={{ backgroundColor: theme.primary }}
            >
                <Link to='/projects'>
                    <AiOutlineHome className={classes.home} />
                </Link>
                <h1 style={{ color: theme.secondary }}>
                    {project.projectName}
                </h1>
            </div>
            <div className='projectDetailPage-container'>
                {loading ? (
                    <div
                        className='projectDetailPage-loading'
                        style={{ color: theme.tertiary }}
                    >
                        Loading...
                    </div>
                ) : (
                    <div
                        className='markdown-body'
                        style={{ color: theme.tertiary }}
                    >
                        <ReactMarkdown
                            remarkPlugins={[remarkGfm]}
                            rehypePlugins={[rehypeRaw]}
                            components={{
                                h1: ({ children, ...props }) => {
                                    const id = generateSlug(children)
                                    return <h1 id={id} {...props}>{children}</h1>
                                },
                                h2: ({ children, ...props }) => {
                                    const id = generateSlug(children)
                                    return <h2 id={id} {...props}>{children}</h2>
                                },
                                h3: ({ children, ...props }) => {
                                    const id = generateSlug(children)
                                    return <h3 id={id} {...props}>{children}</h3>
                                },
                                a: ({ href, children, ...props }) => {
                                    const isAnchor = href && href.startsWith('#')
                                    return isAnchor ? (
                                        <a
                                            href={href}
                                            style={{ color: theme.primary }}
                                            {...props}
                                        >
                                            {children}
                                        </a>
                                    ) : (
                                        <a
                                            href={href}
                                            target='_blank'
                                            rel='noreferrer'
                                            style={{ color: theme.primary }}
                                            {...props}
                                        >
                                            {children}
                                        </a>
                                    )
                                },
                                code: ({ children, ...props }) => (
                                    <code
                                        style={{
                                            backgroundColor:
                                                theme.primary + '20',
                                            color: theme.tertiary,
                                        }}
                                        {...props}
                                    >
                                        {children}
                                    </code>
                                ),
                                blockquote: ({ children, ...props }) => (
                                    <blockquote
                                        style={{
                                            borderLeftColor: theme.primary,
                                        }}
                                        {...props}
                                    >
                                        {children}
                                    </blockquote>
                                ),
                                th: ({ children, ...props }) => (
                                    <th
                                        style={{
                                            borderColor:
                                                theme.tertiary + '30',
                                        }}
                                        {...props}
                                    >
                                        {children}
                                    </th>
                                ),
                                td: ({ children, ...props }) => (
                                    <td
                                        style={{
                                            borderColor:
                                                theme.tertiary + '30',
                                        }}
                                        {...props}
                                    >
                                        {children}
                                    </td>
                                ),
                            }}
                        >
                            {markdown}
                        </ReactMarkdown>
                    </div>
                )}
            </div>
        </div>
    )
}

export default ProjectDetailPage